'@
    $ExpectedSha256 = '2258ddab94dca9c9e66b2639cd7dfdff486678ca5a425a5fc35b86bc9891d4a3'
    $Bytes = [Convert]::FromBase64String($PayloadBase64)
    $Hasher = [Security.Cryptography.SHA256]::Create()
    try { $ActualSha256 = ([BitConverter]::ToString($Hasher.ComputeHash($Bytes))).Replace('-','').ToLowerInvariant() }
    finally { $Hasher.Dispose() }
    if ($ActualSha256 -ne $ExpectedSha256) { throw 'Installer content is incomplete: SHA-256 mismatch. Original project was not changed.' }

    $Parent = Split-Path $Original -Parent
    $Target = Join-Path $Parent ('csv-import-pipeline-fixed-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [Guid]::NewGuid().ToString('N').Substring(0,6))
    if (Test-Path -LiteralPath $Target) { throw ('Target already exists: ' + $Target) }
    New-Item -ItemType Directory -Path $Target | Out-Null

    function Copy-CourseDependency([string]$From, [string]$To) {
        New-Item -ItemType Directory -Path $To -Force | Out-Null
        foreach ($Item in (Get-ChildItem -LiteralPath $From -Force)) {
            if ($Item.Name -eq '.git') { continue }
            $Next = Join-Path $To $Item.Name
            if ($Item.PSIsContainer) { Copy-CourseDependency $Item.FullName $Next }
            else { Copy-Item -LiteralPath $Item.FullName -Destination $Next }
        }
    }
    Write-Host 'Copying the existing GoogleTest dependency (excluding .git metadata)...'
    Copy-CourseDependency (Join-Path $Original 'third_party') (Join-Path $Target 'third_party')

    $DataTarget = Join-Path $Target 'data'
    New-Item -ItemType Directory -Path $DataTarget -Force | Out-Null
    $SmallFiles = @('sample_utf8.csv','sample_noeol.csv','sample_gbk.csv','sample_dirty.csv','sample_quote.csv','sample_crlf.csv','sample_100k.csv','demo_err.csv','ReadMe.md','output.txt','test.txt')
    foreach ($Name in $SmallFiles) {
        $Source = Join-Path (Join-Path $Original 'data') $Name
        if (!(Test-Path -LiteralPath $Source)) { throw ('Missing small data file: ' + $Source) }
        if ((Get-Item -LiteralPath $Source).Length -gt 10000000) { throw ('Unexpected large file: ' + $Source) }
        $TargetName = $Name
        if ($Name -eq 'ReadMe.md') { $TargetName = 'COURSE_DATA_README.md' }
        Copy-Item -LiteralPath $Source -Destination (Join-Path $DataTarget $TargetName)
    }

    Add-Type -AssemblyName System.IO.Compression
    $Stream = [IO.MemoryStream]::new($Bytes, $false)
    $Archive = [IO.Compression.ZipArchive]::new($Stream, [IO.Compression.ZipArchiveMode]::Read, $false)
    $Prefix = $Target.TrimEnd([IO.Path]::DirectorySeparatorChar) + [IO.Path]::DirectorySeparatorChar
    try {
        foreach ($Entry in $Archive.Entries) {
            $Destination = [IO.Path]::GetFullPath((Join-Path $Target $Entry.FullName))
            if (!$Destination.StartsWith($Prefix, [StringComparison]::OrdinalIgnoreCase)) { throw 'Unsafe embedded ZIP path' }
            if (!$Entry.Name) { New-Item -ItemType Directory -Path $Destination -Force | Out-Null; continue }
            New-Item -ItemType Directory -Path ([IO.Path]::GetDirectoryName($Destination)) -Force | Out-Null
            $InputStream = $Entry.Open()
            $OutputStream = [IO.File]::Open($Destination, [IO.FileMode]::Create, [IO.FileAccess]::Write)
            try { $InputStream.CopyTo($OutputStream) }
            finally { $OutputStream.Dispose(); $InputStream.Dispose() }
        }
    } finally { $Archive.Dispose(); $Stream.Dispose() }

    # Ensure every supplied small CSV was copied without any byte conversion.
    $Manifest = Get-Content -LiteralPath (Join-Path $Target 'evidence\original-data-manifest.json') -Raw | ConvertFrom-Json
    foreach ($File in $Manifest) {
        if ($File.name -notlike '*.csv') { continue }
        $Copied = Join-Path $Target $File.stored_path
        $Hash = (Get-FileHash -LiteralPath $Copied -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($Hash -ne $File.sha256) { throw ('Original CSV differs from the verified attachment: ' + $File.name) }
    }
    $OriginalData = Join-Path $Original 'data'
    [IO.File]::WriteAllText((Join-Path $Target 'ORIGINAL_DATA_PATH.txt'), $OriginalData, [Text.UTF8Encoding]::new($false))
    Write-Host ''
    Write-Host 'Created the fixed project successfully:' -ForegroundColor Green
    Write-Host $Target
    Write-Host ''
    Write-Host 'The ORIGINAL project and its 1 GB data were not modified.'
    Write-Host 'Next command (run tests and measure the ORIGINAL 1 GB file):'
    $CheckScript = Join-Path $Target 'scripts\Run-WindowsChecks.ps1'
    Write-Host ('powershell -ExecutionPolicy Bypass -File "' + $CheckScript + '" -DataDir "' + $OriginalData + '"')
    Invoke-Item -LiteralPath $Target
}
